def f(inp):
    g=np.array(inp); out=g.copy()
    pts=[tuple(map(int,p)) for p in np.argwhere(g==4)]
    ys=[r for r,_ in pts]; xs=[c for _,c in pts]
    mpts=[tuple(map(int,p)) for p in np.argwhere(g==6)]
    my=[r for r,_ in mpts]; mx=[c for _,c in mpts]
    vert = (max(my)-min(my))>= (max(mx)-min(mx))
    if vert:
        tops=[c for r,c in mpts if r==min(my)]; bots=[c for r,c in mpts if r==max(my)]
        tip='top' if len(tops)<len(bots) else 'bottom'
        line = max(ys) if tip=='top' else min(ys)
        tr=[(2*line+1-r,c) for r,c in pts]
    else:
        lefts=[r for r,c in mpts if c==min(mx)]; rights=[r for r,c in mpts if c==max(mx)]
        tip='left' if len(lefts)<len(rights) else 'right'
        line = max(xs) if tip=='left' else min(xs)
        tr=[(r,2*line+1-c) for r,c in pts]
    for r,c in tr:
        if 0<=r<g.shape[0] and 0<=c<g.shape[1]:
            if out[r][c]!=6: out[r][c]=4   # paint copy even where old marker was
    return out.tolist()
